typedef unsigned int size_t;

class stringx { char data[8]; };
class Font;
class MultiLineString;

class color32 {
public:
    unsigned int value;
    color32(int, int, int, int);
};

class FEMenuEntry;
class FEMenuSystem {
    char button_down[28];
    int device_flags;
public:
    void *menus;
    void *manager;
    int active;
    int size;
    int count;
    Font *font;
};

class FEMenu {
public:
    int center_x, center_y, num_entries, dy, half, menu_num;
    bool init;
    stringx font_filename;
    color32 color, color_high, color_high_alt;
    float scale, scale_high;
    int max_vis_entries, flags;
    FEMenuEntry *entries, *first_vis_entry, *last_vis_entry, *highlighted;
    FEMenuSystem *system;
};

class MultiLineString {
public:
    MultiLineString(Font *, stringx, float, float);
    void changeScale(float);
    color32 color;
    bool no_color;
};

class FloatingText : public MultiLineString {
public:
    FloatingText(Font *, stringx);
};

class FEMenuEntry {
public:
    int entry_num;
    FEMenuEntry *next;
    FEMenuEntry *previous;
    FEMenu *menu;
protected:
    bool highlight;
    bool disabled;
    void *ent;
    color32 high_ent_color;
    color32 norm_ent_color;
    MultiLineString *text;
private:
    float highlight_intensity;
    float highlight_timer;
    int disabled_alpha;
    color32 special_color;
    color32 special_color_high;
    bool has_special_color;
    bool no_flash;
    float special_scale;
    float special_scale_high;
    bool has_special_scale;
public:
    FEMenuEntry *up, *down, *left, *right;
    void cons(stringx, FEMenu *, bool, Font *);
};

void *operator new(size_t, unsigned int, const char *, int);
#define NEW new(0, (const char *)0x004C3438, 0)
#define NULL 0
enum { FEMENU_HAS_COLOR = 4 };

void FEMenuEntry::cons(stringx l, FEMenu* m, bool floating, Font* ft)
{
	menu = m;
	if(!ft) ft = menu->system->font;
	if(floating) text = NEW FloatingText(ft, l);
	else text = NEW MultiLineString(ft, l, 0, 0);
	next = NULL;
	previous = NULL;
	highlight = false;
	disabled = false;
	if(m->flags & FEMENU_HAS_COLOR) text->color = m->color;
	text->no_color = !(menu->flags & FEMENU_HAS_COLOR);
	text->changeScale(m->scale);
	high_ent_color = color32(255, 255, 255, 255);
	norm_ent_color = color32(255, 255, 255, 255);
	ent = NULL;
	up = NULL;
	down = NULL;
	left = NULL;
	right = NULL;
	highlight_intensity = 0.0f;
	has_special_color = false;
	has_special_scale = false;
	highlight_timer = 0.0f;
	no_flash = false;
	disabled_alpha = 64;
}
